#include "sm121_integer_core.h"
#include <algorithm>
#include <cassert>
#include <cstdio>
#include <fstream>
#include <vector>
using namespace qrt_sm121_integer_core;
using qrt_q1_moe_hawkeye::Value;
std::vector<uint16_t> read(const char* path,size_t n){std::ifstream f(path,std::ios::binary|std::ios::ate);assert(f&&size_t(f.tellg())==n*2u);std::vector<uint16_t> v(n);f.seekg(0);assert(bool(f.read(reinterpret_cast<char*>(v.data()),n*2u)));return v;}
void narrow(Row& r,unsigned retained){
 prepare(r);if(r.unit<0)return;
 r.unit=!r.nonzero?127:r.maximum>int(retained+1u)?r.maximum-int(retained):1;
 r.exceptions=0;
 for(unsigned word=0;word<4;++word){r.trailing[word]=0;for(unsigned byte=0;byte<4;++byte){
  const unsigned i=word*4u+byte;const auto x=r.original[i];const int shift=int((x>>7)&255u)-r.unit;
  if((x&0x7fffu)&&shift<0&&(-shift>=8||((128u|(x&127u))&((1u<<(-shift))-1u))))r.exceptions|=1u<<i;
  r.trailing[word]|=qrt_sm121_integer_parts::trailing_bits(encode(x,r.unit))<<(byte*8u);
 }}
}
int main(int argc,char** argv){
 assert(argc==3);const auto q=read(argv[1],7169u*4096u),k=read(argv[2],7169u*512u);
 for(unsigned width=3;width<=7;++width){
  uint32_t state=0x39520269u;auto random=[&](){state^=state<<13;state^=state>>17;state^=state<<5;return state;};
  size_t groups=0,exceptions=0,loss=0,none=0,exception_hist[17]{},shift_hist[97]{};
  for(unsigned sample=0;sample<65536u;++sample){
   const unsigned qr=random()%7169u,kr=random()%(qr+1u),head=random()%16u;
   const auto* a0=q.data()+(size_t(qr)*16u+head)*256u;const auto* b0=k.data()+(size_t(kr)*2u+head/8u)*256u;
   Value carry{0u,-133,false};
   for(unsigned base=0;base<256;base+=16){
    Row a{},b{};Value terms[17];terms[0]=carry;
    for(unsigned i=0;i<16;++i){a.original[i]=a0[base+i];b.original[i]=b0[base+i];terms[i+1]=qrt_q1_moe_hawkeye::multiply_bf16(a.original[i],b.original[i],-133);}
    narrow(a,width);narrow(b,width);assert(a.unit>=0&&b.unit>=0);
    int maximum=std::max(-133,int(carry.exponent));if(a.maximum+b.maximum-254>maximum)maximum=paired_maximum(a,b,maximum);
    const int shift=maximum-(a.unit+b.unit-254)-11;assert(shift>=-32&&shift<=64);++shift_hist[shift+32];
    const unsigned ex=(a.exceptions|b.exceptions)&a.nonzero&b.nonzero,ls=shift>0?remainder_mask(a,b,unsigned(shift)):0u;
    ++groups;exceptions+=__builtin_popcount(ex);loss+=__builtin_popcount(ls);none+=!(ex|ls);++exception_hist[__builtin_popcount(ex)];
    carry=qrt_q1_moe_hawkeye::group_sum<26,-133>(terms,17);
   }
  }
  std::printf("{\"kind\":\"modular_core_width_coverage\",\"retained_exponent_bits\":%u,\"sampled_complete_dots\":65536,\"groups\":%zu,\"encoding_exception_pairs\":%zu,\"discarded_core_pairs\":%zu,\"no_correction_groups\":%zu,\"exception_pair_histogram\":[",width,groups,exceptions,loss,none);
  for(unsigned i=0;i<17;++i)std::printf("%s%zu",i?",":"",exception_hist[i]);std::printf("],\"shift_histogram\":{");
  bool comma=false;for(unsigned i=0;i<97;++i)if(shift_hist[i]){std::printf("%s\"%d\":%zu",comma?",":"",int(i)-32,shift_hist[i]);comma=true;}
  std::puts("},\"cpu_classification_only\":true,\"native_wmma_checked\":false,\"inference_acceptance\":false,\"performance_acceptance\":false}");
 }
}

